// ---- Tunable configuration ------------------------------------------
const TIMEZONE = 'Africa/Lagos';
// ----------------------------------------------------------------------

// The Error Trigger hands over one of two shapes: `execution` when a running
// workflow threw, or `trigger` when the trigger itself could not start. Read
// both so a poll/webhook failure is not reported as an empty error.
const d = $input.first().json;
const ex = d.execution || {};
const tr = d.trigger || {};
const wf = d.workflow || {};

const err = ex.error || tr.error || {};

let failedNode = ex.lastNodeExecuted;
if (!failedNode) failedNode = tr.error ? '(trigger could not start)' : 'unknown node';

function esc(v) {
  return String(v == null ? '' : v)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const workflowName = wf.name || 'Unknown workflow';
const errorMessage = err.message || 'No error message supplied';
const stack = err.stack || '';
const when = $now.setZone(TIMEZONE).toFormat('cccc, dd LLLL yyyy HH:mm:ss') + ' WAT';
const executionUrl = ex.url || '';

let body = '<p><b>A Tito Finance tracker workflow failed.</b></p>'
  + '<table cellpadding="6" style="border-collapse:collapse">'
  + '<tr><td><b>Workflow</b></td><td>' + esc(workflowName) + '</td></tr>'
  + '<tr><td><b>Failed node</b></td><td>' + esc(failedNode) + '</td></tr>'
  + '<tr><td><b>When</b></td><td>' + esc(when) + '</td></tr>'
  + '<tr><td><b>Error</b></td><td>' + esc(errorMessage) + '</td></tr>'
  + '</table>';

if (executionUrl) {
  body += '<p><a href="' + esc(executionUrl) + '">Open the failed execution in n8n</a></p>';
}

if (stack) {
  body += '<p><b>Stack trace</b></p><pre style="white-space:pre-wrap;font-size:12px">'
    + esc(stack) + '</pre>';
}

body += '<hr><p style="color:#666;font-size:12px">Sent by the Tito Finance Error Handler. '
  + 'Every tracker workflow points at it via Settings &gt; Error Workflow.</p>';

return [{ json: {
  workflowName: workflowName,
  failedNode: failedNode,
  errorMessage: errorMessage,
  timestamp: when,
  executionUrl: executionUrl,
  emailBody: body,
} }];
